package server

func init() {
	pages["sna_circuits"] = `{{define "content"}}
<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h1 class="mb-1">{{if .All}}All SNA circuits{{else}}SNA circuits{{end}}</h1><p class="text-muted mb-0">A circuit is a snusnu transport path between two routers and may carry one or more IBM SNA sessions.</p></div><a class="btn btn-outline-primary" href="{{if .All}}/admin/circuits{{else}}/circuits{{end}}">Refresh</a></div>
<section class="card shadow-sm mb-4"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h4">Active circuits</h2><span class="badge text-bg-primary">{{len .Active}}</span></div><div class="table-responsive"><table class="table table-sm table-striped align-middle mb-0"><thead><tr><th>Circuit</th><th>Path</th><th>State / profile</th><th>Activity</th><th>Transport credit</th><th>Statistics</th><th></th></tr></thead><tbody>{{range .Active}}<tr><td><code>{{.ID}}</code><br><small>opened {{date .OpenedAt}}</small></td><td><a href="/routers/{{.SourceRouterID}}">{{.SourceRouterName}}</a> → <a href="/routers/{{.TargetRouterID}}">{{.TargetRouterName}}</a></td><td><span class="badge text-bg-success">{{.State}}</span><br><small>{{.Profile}}</small></td><td>{{date .LastActivityAt}}</td><td><small>Source: {{.SourceBytes}} / {{.SourceAllowance}} bytes<br>Target: {{.TargetBytes}} / {{.TargetAllowance}} bytes</small></td><td><small>Events: {{.SourceEvents}} / {{.TargetEvents}}<br>Peak queue: {{.PeakQueuedBytes}} bytes</small></td><td><form method="post" action="{{if $.All}}/admin/circuits/{{.ID}}/reset{{else}}/circuits/{{.ID}}/reset{{end}}" onsubmit="return confirm('Reset this SNA circuit? Both routers will be notified and the carried SNA sessions will end.')"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="btn btn-outline-danger btn-sm">Reset circuit</button></form></td></tr>{{else}}<tr><td colspan="7">No active SNA circuits.</td></tr>{{end}}</tbody></table></div></div></section>
<section class="card shadow-sm"><div class="card-body"><h2 class="h4">Circuit history</h2><p class="text-muted">Completed transport summaries are retained for 90 days. SNA payloads are not stored.</p><div class="table-responsive"><table class="table table-sm table-striped align-middle mb-0"><thead><tr><th>Circuit</th><th>Path</th><th>Profile</th><th>Duration</th><th>Result</th><th>Statistics</th></tr></thead><tbody>{{range .History}}<tr><td><code>{{.ID}}</code><br><small>{{date .OpenedAt}} – {{date .ClosedAt}}</small></td><td>{{.SourceRouterName}} → {{.TargetRouterName}}</td><td>{{.Profile}}</td><td>{{if .ActivatedAt}}Activated {{date .ActivatedAt}}{{else}}Never activated{{end}}</td><td><span class="badge {{if eq .State "closed"}}text-bg-secondary{{else}}text-bg-warning{{end}}">{{.State}}</span><br><small>{{.CloseReason}}{{if .ActorID}}<br>{{.ActorType}}: {{.ActorID}}{{end}}</small></td><td><small>Bytes: {{.SourceBytes}} / {{.TargetBytes}}<br>Events: {{.SourceEvents}} / {{.TargetEvents}}<br>Peak queue: {{.PeakQueuedBytes}} bytes</small></td></tr>{{else}}<tr><td colspan="6">No completed SNA circuits in retained history.</td></tr>{{end}}</tbody></table></div></div></section>
{{end}}`
}
